    if wine_glasses_on_tablecloth:
        return max(wine_glasses_on_tablecloth, key=lambda wg: wg.horizontal_center)

    if wine_glasses_next_to_plate:
        return max(wine_glasses_next_to_plate, key=lambda wg: wg.horizontal_center)

    return wine_glass_patches[0]

